from django.views import View
from django.http import JsonResponse, Http404, HttpResponseForbidden
from django.contrib.auth.mixins import LoginRequiredMixin
from actstream.models import model_stream
from .models import WorkspaceProject

class ProjectActivityFeedView(LoginRequiredMixin, View):
    def get(self, request, project_id):
        try:
            project = WorkspaceProject.objects.get(id=project_id)
        except WorkspaceProject.DoesNotExist:
            raise Http404("Project not found")

        # Check membership within the project's workspace team
        if not project.members.filter(id=request.user.id).exists() and project.organization != request.user.organization:
            return HttpResponseForbidden("Access denied: You are not a member of this project")

        actions = model_stream(project)[:25]
        data = [{
            "id": act.id,
            "verb": act.verb,
            "actor": act.actor.username if act.actor else None,
            "target": str(act.target) if act.target else None,
            "created_at": act.timestamp.isoformat()
        } for act in actions]
        return JsonResponse({"project_id": str(project.id), "activity": data})
